import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'package:flutter/material.dart';
import 'package:audioplayers/audioplayers.dart';
import 'package:image_picker/image_picker.dart';
import 'package:path_provider/path_provider.dart';
import 'package:record/record.dart';
import '../core/theme/app_theme.dart';
import '../services/api_client.dart';

class HelpTeamScreen extends StatefulWidget {
  const HelpTeamScreen({super.key, required this.accessToken});
  final String? accessToken;
  @override State<HelpTeamScreen> createState()=>_HelpTeamScreenState();
}
class _HelpTeamScreenState extends State<HelpTeamScreen>{
 final api=ApiClient(),text=TextEditingController(),scroll=ScrollController(),recorder=AudioRecorder(),picker=ImagePicker(),player=AudioPlayer();
 final messages=<Map<String,dynamic>>[]; Timer? poll; bool loading=true,sending=false,recording=false; String? error;
 @override void initState(){super.initState();load();poll=Timer.periodic(const Duration(seconds:5),(_)=>load(silent:true));}
 @override void dispose(){poll?.cancel();text.dispose();scroll.dispose();recorder.dispose();player.dispose();super.dispose();}
 Future<void> load({bool silent=false}) async {if(!silent&&mounted)setState(()=>loading=true);try{final d=await api.get('/api/support/chat',accessToken:widget.accessToken);final rows=(d['messages'] as List? ??const []).whereType<Map>().map((x)=>Map<String,dynamic>.from(x)).toList();if(mounted)setState(() { messages..clear()..addAll(rows); error=null; loading=false; });WidgetsBinding.instance.addPostFrameCallback((_){if(scroll.hasClients)scroll.jumpTo(scroll.position.maxScrollExtent);});}catch(e){if(mounted)setState(() { error=e.toString(); loading=false; });}}
 Future<void> send({List<Map<String,dynamic>> attachments=const []}) async {final value=text.text.trim();if((value.isEmpty&&attachments.isEmpty)||sending)return;setState(()=>sending=true);try{final d=await api.post('/api/support/chat',accessToken:widget.accessToken,body:{'text':value,'attachments':attachments});if(d['message'] is Map){setState(()=>messages.add(Map<String,dynamic>.from(d['message'])));text.clear();}await load(silent:true);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}finally{if(mounted)setState(()=>sending=false);}}
 Future<void> imageMessage() async {final x=await picker.pickImage(source:ImageSource.gallery,imageQuality:75,maxWidth:1400);if(x==null)return;final bytes=await x.readAsBytes();if(bytes.length>4*1024*1024){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Choose an image under 4 MB.')));return;}final mime=x.mimeType??'image/jpeg';await send(attachments:[{'name':x.name,'mime':mime,'kind':'image','data':'data:'+mime+';base64,'+base64Encode(bytes)}]);}
 Future<void> playVoice(String data) async {try{final encoded=data.split(',').last;await player.play(BytesSource(base64Decode(encoded)));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Could not play this voice note.')));}}
 Future<void> voiceMessage() async {if(recording){final path=await recorder.stop();setState(()=>recording=false);if(path==null)return;final bytes=await File(path).readAsBytes();if(bytes.length>4*1024*1024){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Voice note is too large; record a shorter one.')));return;}await send(attachments:[{'name':'voice-message.m4a','mime':'audio/mp4','kind':'audio','data':'data:audio/mp4;base64,'+base64Encode(bytes)}]);return;}if(!await recorder.hasPermission()){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Microphone permission is required.')));return;}final dir=await getTemporaryDirectory();final path=dir.path+'/numelixa-voice-'+DateTime.now().millisecondsSinceEpoch.toString()+'.m4a';await recorder.start(const RecordConfig(encoder:AudioEncoder.aacLc),path:path);setState(()=>recording=true);}
 @override Widget build(BuildContext context){return Scaffold(appBar:AppBar(title:const Text('Help Team')),body:Column(children:[Container(margin:const EdgeInsets.all(12),padding:const EdgeInsets.all(14),decoration:BoxDecoration(borderRadius:BorderRadius.circular(18),gradient:const LinearGradient(colors:[Color(0xff102d4d),Color(0xff151c3b)])),child:const Row(children:[Icon(Icons.support_agent,color:AppTheme.cyan,size:34),SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Numelixa Support',style:TextStyle(fontWeight:FontWeight.bold)),Text('Private chat · Text, images and voice notes',style:TextStyle(fontSize:12,color:Colors.white70))]))])),if(error!=null)Text(error!,style:const TextStyle(color:Colors.orangeAccent)),Expanded(child:loading&&messages.isEmpty?const Center(child:CircularProgressIndicator()):messages.isEmpty?const Center(child:Text('Start a conversation with our Help Team.')):ListView.builder(controller:scroll,padding:const EdgeInsets.all(12),itemCount:messages.length,itemBuilder:(context,i){final m=messages[i],mine=m['senderRole']!='admin';final attachments=(m['attachments'] as List? ??const []);return Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:Container(constraints:const BoxConstraints(maxWidth:310),margin:const EdgeInsets.symmetric(vertical:5),padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:mine?const Color(0xff123c55):const Color(0xff1c2540),borderRadius:BorderRadius.circular(16),border:Border.all(color:AppTheme.cyan.withOpacity(.15))),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(mine?'You':'Numelixa Help Team',style:const TextStyle(color:AppTheme.cyan,fontWeight:FontWeight.bold,fontSize:11)),if((m['text']??'').toString().isNotEmpty)Padding(padding:const EdgeInsets.only(top:5),child:Text(m['text'].toString())),...attachments.whereType<Map>().map((a){final kind=(a['kind']??'').toString();final data=(a['data']??'').toString();if(kind=='image'&&data.contains(',')){try{return Padding(padding:const EdgeInsets.only(top:8),child:Image.memory(base64Decode(data.split(',').last),width:220,fit:BoxFit.cover));}catch(_){}}if(kind=='audio'&&data.contains(',')){return TextButton.icon(onPressed:()=>playVoice(data),icon:const Icon(Icons.play_circle,color:AppTheme.cyan),label:const Text('Play voice message'));}return Row(children:[const Icon(Icons.attach_file,color:AppTheme.cyan),Flexible(child:Text((a['name']??'Attachment').toString()))]);})])));})),SafeArea(top:false,child:Padding(padding:const EdgeInsets.all(8),child:Row(children:[IconButton(onPressed:sending?null:imageMessage,icon:const Icon(Icons.image_outlined,color:AppTheme.cyan)),IconButton(onPressed:sending?null:voiceMessage,icon:Icon(recording?Icons.stop_circle:Icons.mic_none,color:recording?Colors.redAccent:AppTheme.cyan)),Expanded(child:TextField(controller:text,minLines:1,maxLines:4,decoration:InputDecoration(hintText:recording?'Recording…':'Message Help Team',border:OutlineInputBorder(borderRadius:BorderRadius.circular(22))),onSubmitted:(_)=>send())),IconButton(onPressed:sending?null:()=>send(),icon:const Icon(Icons.send_rounded,color:AppTheme.cyan))]))) ]));}
}